  (* [comment removed for export] *)
  Definition mss_segB1_post (sp gp tp s0 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (q implb ioc lo : Z) (ivp iu ii : Z) (ij7 : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists ra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' jm1 jm2,
      ms' = MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -128)) gp tp t0 t1 t2
                    s0 (Z_to_bv 64 (q + 24)) a0 a1 a2 a3 a4 a5 a6 a7
                    (Z_to_bv 64 (q + 32)) (Z_to_bv 64 0) (Z_to_bv 64 (implb + 32)) (Z_to_bv 64 implb) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_MSS_MID) fc None m' (seg_rom rsegs)
      /\ munch [(lo, bv_unsigned sp + -72); (q + 32, q + 80); (implb + 12, implb + 16)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ stk rsegs m' lo (bv_unsigned sp + -128)
      /\ rw_cells rsegs m' (bv_unsigned sp + -128)
           [C8 (wz ioc); CB 16 jm1; C8 (wz 0); C8 (wz 0); C8 (wz 0); C8 (wz T_ANYEX_PROP_FNS)]
      /\ rw_cells rsegs m' (q + 32) [C8 (wz ioc); CB 16 jm2; C8 (wz T_ANYEX_OBJECT_FNS); C8 (wz (q + 32)); C8 (wz T_ANYEX_TARGET_FNS)]
      /\ rw_cells rsegs m' implb (SpcHdrCells (mkSPC ivp iu 2 ii) ij7).
Scheme kc__3 := Elimination for Corelib.Init.Datatypes.bool Sort Prop.

  Lemma mss_segB1 : forall (rax : word) sp gp tp t0 t1 t2 s0 (s1x : word) a0 a1 a2 a3 a4 a5 a6 a7 (s2x : word) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (q implb ioc EX SPP FCP lo : Z) (ivp iu ii : Z) (j7 j48 j8 jd j16 ij7 : list byte),
    rw_cells rsegs m (bv_unsigned sp + -64) [C8 (Z_to_bv 64 q)] ->
    rw_cells rsegs m (bv_unsigned sp + -128) [CB 48 j48] ->
    rw_cells rsegs m (bv_unsigned sp + -80) [CB 8 j8] ->
